  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Formal Commands with Usted and Ustedes$j$, $j${"readings": [{"title": "Matthew 11 (King James Version)", "url": "/portal/bible/Matthew/11"}], "body": "Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest. This verse is a command, and commands are how we give directions, invite and serve. In Spanish, you speak politely to a pastor, a teacher or a stranger with the formal commands, usted for one person and ustedes for more than one.\n\nTo form them, start with the yo form of the present tense, drop the o, and add the opposite vowel. Ar verbs take e and en. Er and ir verbs take a and an. Hablar becomes hable and hablen. Comer becomes coma and coman. Escribir becomes escriba and escriban. Verbs with an irregular yo form keep it: tener, tengo, tenga; hacer, hago, haga; venir, vengo, venga; decir, digo, diga.\n\nSpelling changes keep the sound: buscar becomes busque, pagar becomes pague and empezar becomes empiece. Five verbs are completely irregular: ser, sea; ir, vaya; estar, esté; dar, dé; saber, sepa.\n\nFor the negative, put no before the command. Pronouns attach to an affirmative command and go before a negative one. Siéntese, por favor. No se siente. Dígame la verdad.\n\nWorked example: Pase, siéntese y abra su Biblia. Venga con nosotros. Common mistake: using the infinitive as a command or forgetting the accent when a pronoun is attached. Siéntese needs the accent.\n\nYour task: (1) Write the usted and ustedes commands for hablar, comer, escribir and venir. (2) Write six polite commands a greeter at church might say.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest. That is a command.\n\nNow watch this. Formal commands are for usted and ustedes. Start with the yo form, drop the o, add the opposite vowel. Ar verbs take e, en. Er and ir verbs take a, an. Hable, coma, escriba. Hablen, coman, escriban.\n\nIrregular yo forms carry over. Tenga, haga, venga, diga.\n\nFive verbs are irregular: sea, vaya, esté, dé, sepa.\n\nPronouns attach to affirmative commands. Siéntese. Dígame. For a negative, the pronoun goes before. No se siente.\n\nYour task is to write formal commands for four verbs and six polite church commands. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Formal Commands with Usted and Ustedes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Informal Commands with Tú$j$, $j${"readings": [{"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}], "body": "Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. The first half is a positive command and the second is a negative command. With friends, family and children, Spanish uses tú commands.\n\nThe affirmative tú command is the same as the él form of the present tense. Habla, come, escribe. Habla más despacio. Come tu desayuno. Eight common verbs are irregular in the affirmative: decir, di; hacer, haz; ir, ve; poner, pon; salir, sal; ser, sé; tener, ten; venir, ven. Ven a la iglesia. Haz tu tarea. Di la verdad.\n\nThe negative tú command uses the usted pattern with an s: take the yo form, drop the o, and add the opposite vowel plus s. No hables, no comas, no escribas. Irregular negatives are no vayas, no seas, no des, no estés. No tengas miedo. No digas mentiras.\n\nPronouns attach to the affirmative and go before the negative: Dime la verdad, no me mientas. Hazlo ahora, pero no lo hagas con prisa.\n\nWorked example: Confía en el Señor y no te preocupes. Lee tu Biblia, escucha a tus padres y no dejes de orar. Common mistake: using the tú command with an elder. Use usted commands with pastors, teachers and strangers.\n\nYour task: (1) Give the affirmative and negative tú commands for hablar, comer, hacer and ir. (2) Write six pieces of advice for a younger cousin.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. A positive command and a negative command in one verse.\n\nNow watch this. The affirmative tú command is the él form. Habla, come, escribe.\n\nEight irregular affirmatives: di, haz, ve, pon, sal, sé, ten, ven.\n\nThe negative tú command takes the yo form, drops the o and adds the opposite vowel plus s. No hables, no comas, no escribas. Irregulars: no vayas, no seas, no des, no estés.\n\nPronouns attach to affirmative commands and go before negative ones. Dime la verdad. No me mientas.\n\nUse tú with friends and family, and usted with elders.\n\nYour task is to give affirmative and negative commands and write six pieces of advice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Informal Commands with Tú$j$);
end
$seed$;
